import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"同じ contract に 3 layer を重ねる","description":"","frontmatter":{},"headers":[],"relativePath":"ja/cookbook/three-layer-stack.md","filePath":"ja/cookbook/three-layer-stack.md"}'),c={name:"ja/cookbook/three-layer-stack.md"};function o(n,e,r,d,l,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="同じ-contract-に-3-layer-を重ねる" tabindex="-1">同じ contract に 3 layer を重ねる <a class="header-anchor" href="#同じ-contract-に-3-layer-を重ねる" aria-label="Permalink to &quot;同じ contract に 3 layer を重ねる&quot;">​</a></h1><blockquote><p><a href="./../../en/cookbook/three-layer-stack">🇬🇧 English</a> • <a href="./three-layer-stack">🇯🇵 日本語</a></p></blockquote><p>kiwa は 1 つの Solidity contract に対して <strong>Foundry (<code>.t.sol</code>) + Hardhat (<code>.test.cjs</code>) + Playwright (<code>.spec.ts</code>)</strong> の 3 layer を並立できる。 この recipe では 3 つの reference contract で同じ構造を歩き、 「1 example だけの偶然」 ではなく汎用的な構造であることを確認する。</p><h2 id="_3-layer-を選ぶべき場面" tabindex="-1">3 layer を選ぶべき場面 <a class="header-anchor" href="#_3-layer-を選ぶべき場面" aria-label="Permalink to &quot;3 layer を選ぶべき場面&quot;">​</a></h2><p>以下のいずれかが当てはまる時は 3 layer 全部を有効にする。</p><ul><li>runner 多様性 (Foundry <code>vm.warp</code> / Hardhat <code>solidity-coverage</code> / Playwright on-chain assertion) で同じバグを別角度から捕捉したい</li><li>contract test (<code>forge test</code> + <code>npx hardhat test</code>) と UX 級 e2e test (<code>playwright test</code>) を 1 つの Layer 1 spec (<code>/kiwa-design --layer contract</code> と <code>--layer e2e</code>) で同期させたい</li><li>contract surface と dApp surface 両方を 1 regression suite に含めたい</li></ul><p>contract correctness だけなら Foundry 単独で十分、 UX だけなら Playwright 単独で十分。 3 layer を組むのは上記を同時に整合させたい時に効く。</p><h2 id="_3-つの-reference-contract" tabindex="-1">3 つの reference contract <a class="header-anchor" href="#_3-つの-reference-contract" aria-label="Permalink to &quot;3 つの reference contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>Contract</th><th>Foundry lane</th><th>Hardhat lane</th><th>Playwright lane</th></tr></thead><tbody><tr><td><a href="./../../../tests/fixtures/mint-nft/"><code>tests/fixtures/mint-nft</code></a></td><td><code>MintNft.sol</code> (ERC721 + Enumerable + royalty)</td><td><code>contract-test/MintNft.t.sol</code> (27/27)</td><td><code>hardhat-test/MintNft.test.cjs</code> (24/24)</td><td><code>e2e-test/mint.spec.ts</code> (8/8)</td></tr><tr><td><a href="./../../../tests/fixtures/defi-swap/"><code>tests/fixtures/defi-swap</code></a></td><td><code>SimpleSwap.sol</code> + <code>Erc20.sol</code> (1:1 swap pool with slippage protection)</td><td><code>contract-test/SwapTokens.t.sol</code> (17/17)</td><td><code>hardhat-test/SwapTokens.test.cjs</code> (23/23)</td><td><code>e2e-test/swap.spec.ts</code> (7/7)</td></tr><tr><td><a href="./../../../tests/fixtures/nextjs-token-gating/"><code>tests/fixtures/nextjs-token-gating</code></a></td><td><code>GatedContent.sol</code> (NFT-gated access + timed grant)</td><td><code>contract-test/GatedContent.t.sol</code> (20/20)</td><td><code>hardhat-test/GatedContent.test.cjs</code> (23/23)</td><td><code>e2e-test/gating.spec.ts</code> (8/8)</td></tr></tbody></table><p>各 lane は fixture dir から直接実行できる。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Foundry lane (任意 example)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/fixtures/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:foundry</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Hardhat lane (任意 example)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/fixtures/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:hardhat</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Playwright lane (任意 example)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/fixtures/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e</span></span></code></pre></div><p>9 entry (3 example × 3 lane) で 3 つの contract 形状 (NFT mint / AMM swap / gated content) を cover、 stack が特定 contract pattern に依存していないことを示している。</p><h2 id="同じ-contract-で-3-lane-すべてが通る仕組み" tabindex="-1">同じ contract で 3 lane すべてが通る仕組み <a class="header-anchor" href="#同じ-contract-で-3-lane-すべてが通る仕組み" aria-label="Permalink to &quot;同じ contract で 3 lane すべてが通る仕組み&quot;">​</a></h2><p>共有の Layer 1 spec (<code>tests/spec/contract/test-spec-&lt;name&gt;.md</code> と <code>tests/spec/e2e/test-spec-&lt;name&gt;.md</code>) が単一 SSOT になっている。 Layer 2 skill はこれを読んで機械的に変換する。</p><ul><li><code>/kiwa-forge</code> は spec の TC 表を Foundry helper (<code>vm.expectRevert</code>、 <code>forge fuzz</code>、 <code>vm.warp</code>) に変換</li><li><code>/kiwa-hardhat</code> は同表を Hardhat helper (<code>expect(...).to.be.reverted</code>、 <code>fast-check</code>、 <code>time.increaseTo</code>) に変換</li><li><code>/kiwa-play</code> は e2e TC 表を Playwright + <code>@kiwa-test/dapp</code> fixture helper (<code>getByTestId</code>、 <code>walletClient.signTypedData</code>) に変換</li></ul><p>観点 × runner マッピング表は <a href="./../../../.claude/skills/kiwa-design/references/viewpoints-catalog"><code>viewpoints-catalog.md</code></a> に列挙されており、 contributor は Layer 2 起動前にどんな test code が生成されるかを予測できる。</p><h2 id="_4-つ目の-contract-をこの-stack-に追加するには" tabindex="-1">4 つ目の contract をこの stack に追加するには <a class="header-anchor" href="#_4-つ目の-contract-をこの-stack-に追加するには" aria-label="Permalink to &quot;4 つ目の contract をこの stack に追加するには&quot;">​</a></h2><p><code>examples/&lt;name&gt;/contracts/</code> 配下の任意 contract を選び、 以下の順で skill chain を歩く。</p><ol><li><code>/kiwa-design --layer contract --module &lt;name&gt; --input examples/&lt;name&gt;/contracts/&lt;Contract&gt;.sol</code></li><li><code>/kiwa-forge --module &lt;name&gt;</code> → <code>examples/&lt;name&gt;/test/&lt;Contract&gt;.t.sol</code></li><li><code>/kiwa-hardhat --module &lt;name&gt;</code> → <code>examples/&lt;name&gt;/hardhat-test/&lt;Contract&gt;.test.cjs</code></li><li><code>/kiwa-design --layer e2e --module &lt;name&gt; --input examples/&lt;name&gt;/app/page.tsx</code></li><li><code>/kiwa-play --module &lt;name&gt;</code> → <code>examples/&lt;name&gt;/tests/&lt;name&gt;.spec.ts</code></li></ol><p>時刻依存ロジック (vesting / 投票 deadline) を持つ contract なら、 contract lane は Foundry を優先する (<code>vm.warp</code> で境界時刻を素直に test できる)。 UI が反応する event を多発する contract なら、 e2e lane を Playwright 優先で <code>getByTestId</code> 直接 assertion に倒す。</p><p>runner 固有の制約は spec の <a href="./../../../.claude/skills/kiwa-design/references/output-skeleton"><code>runner 差異</code></a> bullet に記録される、 contributor は片方の runner で到達不能な branch を追わなくて済む。</p><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li><a href="./../../../tests/docs/skill-chain-tutorial.ja"><code>tests/docs/skill-chain-tutorial.ja.md</code></a> — spec から test までの full flow</li><li><a href="./../../../tests/docs/run-contract-tests.ja"><code>tests/docs/run-contract-tests.ja.md</code></a> — contract 側手順 (Foundry + Hardhat)</li><li><a href="./../../../tests/docs/run-dapp-e2e-tests.ja"><code>tests/docs/run-dapp-e2e-tests.ja.md</code></a> — dApp e2e 手順 (Playwright)</li><li><a href="./../../EXAMPLE-FIXTURES.ja"><code>docs/EXAMPLE-FIXTURES.ja.md</code></a> — どの example が完成形 fixture を持つか</li></ul>`,23)])])}const g=t(c,[["render",o]]);export{k as __pageData,g as default};
